import re, csv, pathlib, sys
T = pathlib.Path(sys.argv[1])
po = {}
for r in csv.DictReader(open("data/portal/soony/erp/purchase_orders_2025H2-2026.csv")):
    po[(r["po_number"], int(r["po_line"]))] = r
pat = re.compile(r"(000\d0)\s+(\S+)\s+(.*?)\s+([\d,]+)\s+([\d.]+)\s+(USD|EUR|CNY|INR|KRW)\s+(\d{4}-\d{2}-\d{2})", re.S)
for f in sorted(T.glob("*order_confirmations__OA*")):
    t = f.read_text(); pn = re.search(r"Your order (\d+)", t)
    if not pn: print("NOPO", f.name); continue
    pn = pn.group(1)
    found = pat.findall(t)
    if not found: print("NOPARSE", f.name)
    for it, mat, desc, q, pr, cur, d in found:
        ln = int(it)//10; r = po.get((pn, ln))
        q = int(q.replace(",", ""))
        if not r: print("NOSAP", pn, ln, mat, q, d, f.name); continue
        issues = []
        if r["material_id"] != mat: issues.append(f"mat {r['material_id']}!={mat}")
        if int(r["quantity"]) != q: issues.append(f"qty {r['quantity']}!={q}")
        if r["promised_date"] != d: issues.append(f"date {r['promised_date']}!={d}")
        if abs(float(r["unit_price"]) - float(pr)) > 1e-6: issues.append(f"price {r['unit_price']}!={pr}")
        if issues: print(pn, ln, r["status"], r["material_id"], "|", "; ".join(issues), "|", f.name)
    extra = re.sub(r"\s+", " ", t.split("Confirmed")[-1])
    m = pat.sub("", extra).strip()
    if len(m) > 5: print("  NOTE", pn, ":", m[:300])
EOF
